-- =============================================================================
-- 4. EVENTS: change_log (the single outbox/event table) + consumer cursors
-- =============================================================================
-- Shape PROVEN: every write returns a change event {object_type, object_id, workspace_id, operation c/u, context,
--   relationships, changes[field,before,after]}; versioned per object; client-generated uuids; set edits {add:[],rem:[]}.
-- ASSUMED: seq cursor, depth/origin_rule_id (own design page, automations), hash partitioning, 'd' operation.
-- PARTITION BY HASH (workspace_id) x 16: uniqueness (object, version) needs workspace_id in the key; a tenant's history
-- stays in one partition. Retention = archive + batched DELETE (no per-month drop); see notes.
CREATE SEQUENCE change_log_seq;

CREATE TABLE change_log (
  workspace_id    uuid NOT NULL /* id -> access.workspaces */,
  id              uuid NOT NULL,                     -- client-generated (hist_id style); ON CONFLICT DO NOTHING = idempotent retry
  seq             bigint NOT NULL DEFAULT nextval('change_log_seq'),   -- consumer cursor; ASSUMED
  object_type     text NOT NULL,                     -- task, comment, doc, page, goal, time_entry, automation, ... (open vocabulary)
  object_id       uuid NOT NULL,
  version         integer NOT NULL,                  -- object version AFTER this change (PROVEN versioned events)
  op              text NOT NULL CHECK (op IN ('c','u','d')),   -- c/u PROVEN; d ASSUMED
  actor_id        uuid /* id -> identity.users */,         -- NULL for system
  actor_kind      text NOT NULL DEFAULT 'user' CHECK (actor_kind IN ('user','automation','integration','system')),  -- ASSUMED
  origin_rule_id  uuid,                              -- ASSUMED loop guard: automation that caused this event
  depth           smallint NOT NULL DEFAULT 0,       -- ASSUMED: parent depth + 1 for rule-caused events, stop at 5
  caused_by_event uuid,                              -- ASSUMED causality chain
  changes         jsonb NOT NULL DEFAULT '[]',       -- [{field,before,after}] or [{field,add:[..],rem:[..]}] (PROVEN set edits)
  relationships   jsonb NOT NULL DEFAULT '[]',       -- PROVEN e.g. comment-author, comment-parent, reaction-user
  context         jsonb NOT NULL DEFAULT '{}',       -- PROVEN user, root parent, route, originating service; + list_id for routing
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, id),
  UNIQUE (workspace_id, object_type, object_id, version)   -- per-object order, detects lost updates
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('change_log', 16);

-- consumers read forward: WHERE seq > cursor ORDER BY seq LIMIT n (merge-append over partitions).
CREATE INDEX change_log_seq_idx ON change_log (seq);

-- workspace-wide delta sync for clients (cursor per workspace).
CREATE INDEX change_log_ws_seq ON change_log (workspace_id, seq);

-- (the UNIQUE above doubles as 'history of this object' index: workspace, type, id, version.)
-- 'everything rule X caused' (support, loop forensics).
CREATE INDEX change_log_origin ON change_log (workspace_id, origin_rule_id, created_at) WHERE origin_rule_id IS NOT NULL;

-- indexer queue (global)

-- =============================================================================
-- 10. AUDIT LOG (admin/security events; NOT the change_log)
-- =============================================================================
-- ASSUMED entirely. Append-only, retention by dropping monthly partitions.
-- PARTITION BY RANGE (created_at), monthly.
CREATE TABLE audit_log (
  workspace_id uuid NOT NULL,                        -- no FK: audit must survive workspace deletion
  id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  actor_id uuid,
  actor_kind text NOT NULL DEFAULT 'user' CHECK (actor_kind IN ('user','api_token','automation','integration','system','support')),
  action text NOT NULL,                              -- dotted: member.role_changed, share.link_created, export.started ...
  object_type text,
  object_id uuid,
  result text NOT NULL DEFAULT 'success' CHECK (result IN ('success','denied','failed')),
  ip inet,
  user_agent text,
  request_id text,
  details jsonb NOT NULL DEFAULT '{}',
  PRIMARY KEY (workspace_id, created_at, id)
) PARTITION BY RANGE (created_at);

SELECT support_month_partitions('audit_log', 1, 3);

CREATE TABLE audit_log_default PARTITION OF audit_log DEFAULT;

CREATE INDEX audit_log_ws_time ON audit_log (workspace_id, created_at DESC);

-- admin audit page
CREATE INDEX audit_log_actor ON audit_log (workspace_id, actor_id, created_at DESC) WHERE actor_id IS NOT NULL;

-- 'what did this user do'
CREATE INDEX audit_log_object ON audit_log (workspace_id, object_type, object_id, created_at DESC) WHERE object_id IS NOT NULL;

CREATE INDEX audit_log_action ON audit_log (workspace_id, action, created_at DESC);

CREATE TRIGGER audit_log_no_change BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW EXECUTE FUNCTION audit_log_immutable();

