-- =============================================================================
-- 5. EVENT correlation  (FR-307, FR-020 source)
-- =============================================================================
ALTER TABLE change_log ADD COLUMN correlation_id uuid;

-- one id per bulk action or automation run
ALTER TABLE change_log ADD COLUMN source text NOT NULL DEFAULT 'ui';

-- ui,mobile,api,automation,import,system,form
CREATE INDEX change_log_corr ON change_log (workspace_id, correlation_id) WHERE correlation_id IS NOT NULL;

CREATE TABLE security_events (                              -- L-11, 1 year minimum, append-only, partition by month
  workspace_id uuid,
  id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  user_id uuid,
  kind text NOT NULL,                                       -- login_ok, login_fail, mfa_change, session_revoked, token_used, new_device
  ip inet, user_agent text, details jsonb NOT NULL DEFAULT '{}',
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

SELECT support_month_partitions('security_events', 1, 2);

CREATE TABLE security_events_default PARTITION OF security_events DEFAULT;

CREATE TABLE data_access_log (                              -- L-12 exports, bulk reads, guest views of shared items
  workspace_id uuid NOT NULL,
  id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  actor_id uuid, actor_kind text NOT NULL DEFAULT 'user',
  action text NOT NULL, object_type text, object_id uuid, row_count integer,
  share_link_id uuid, ip inet,
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

SELECT support_month_partitions('data_access_log', 1, 2);

CREATE TABLE data_access_log_default PARTITION OF data_access_log DEFAULT;

CREATE TRIGGER security_events_no_change BEFORE UPDATE OR DELETE ON security_events FOR EACH ROW EXECUTE FUNCTION frd_append_only();

CREATE TRIGGER data_access_log_no_change BEFORE UPDATE OR DELETE ON data_access_log FOR EACH ROW EXECUTE FUNCTION frd_append_only();
